// Derin Öğrenme (PyTorch) cheat sheet. 11 konu.
import type { Topic } from './types'

export const dlGiris: { q: string; a: string }[] = [
  { q: 'Bu başlık ne öğretir?', a: 'PyTorch ile yapay sinir ağı kurmayı ve eğitmeyi. Temeller\'de sinir ağının ne olduğunu anlattık (katmanlar, ağırlıklar, kayıp, gradyan); burada o fikirleri kodla yazacağız: tensör, katman, eğitim döngüsü, görüntü için CNN, hazır modeli kendi verine uyarlama (transfer öğrenme), metin ve ses.' },
  { q: 'Derin öğrenme ile makine öğrenmesi arasındaki fark ne?', a: 'Makine Öğrenmesi başlığında tablo veri vardı: her sütun anlamlı bir özellikti. Görüntü, ses ve metinde böyle hazır özellik yok; bir fotoğraf sadece piksel sayılarıdır. Derin öğrenme, özellikleri de kendisi öğrenir: ilk katmanlar kenarları, sonrakiler şekilleri, en sonkiler "kedi"yi tanır. Bu yüzden ham veride derin öğrenme, tablo veride klasik yöntemler.' },
  { q: 'PyTorch nedir, neden o?', a: 'Meta\'nın geliştirdiği, araştırmada ve üretimde en yaygın derin öğrenme kütüphanesi. Python gibi yazılır, türevleri otomatik alır, GPU\'da çalışır. Hugging Face\'teki modellerin büyük çoğunluğu PyTorch\'tur. TensorFlow ve Keras alternatiftir; kavramlar aynıdır, yazım farklıdır.' },
  { q: 'Tensör ne demek?', a: 'Çok boyutlu sayı tablosu: tek sayı, liste, matris ya da daha fazla boyut. Bir renkli fotoğraf 3 boyutlu tensördür (yükseklik, genişlik, 3 renk kanalı); 32 fotoğrafın grubu 4 boyutlu. PyTorch\'ta her şey tensördür: veri, ağırlıklar, türevler. NumPy dizisine benzer ama GPU\'da çalışır ve türev takip eder.' },
  { q: 'Eğitim döngüsü ne?', a: 'Beş adımlık tekrar: veriyi modelden geçir (tahmin), kaybı hesapla (ne kadar yanlış), eski türevleri temizle, geri yayılımla yeni türevleri hesapla, optimizer ile ağırlıkları güncelle. Bunu tüm veri üzerinde onlarca tur (epoch) döndürürsün. Bu beş satır tüm derin öğrenmenin kalbidir; ezberlemeye değer.' },
  { q: 'GPU şart mı?', a: 'Öğrenmek için hayır: küçük modeller ve küçük veri bilgisayar işlemcisinde çalışır. Gerçek eğitim için evet: sinir ağları milyonlarca çarpma yapar, GPU bunu paralel yaparak günleri saatlere indirir. GPU\'n yoksa Google Colab ve Kaggle tarayıcıda ücretsiz GPU verir; başlangıç için fazlasıyla yeter.' },
  { q: 'Modeli sıfırdan mı eğiteceğim?', a: 'Neredeyse hiç. Milyonlarca görselle eğitilmiş hazır bir modeli (ResNet, ViT) alır, son katmanını kendi sınıflarına göre değiştirir ve birkaç yüz örnekle eğitirsin; buna transfer öğrenme denir. Hem çok az veri hem çok az süre yeter. Bu bölümün en pratik konusu budur.' },
  { q: 'Kodlar neden bu kadar uzun görünüyor?', a: 'scikit-learn\'de fit tek satırdı; PyTorch\'ta eğitim döngüsünü kendin yazarsın, çünkü tam kontrol sende. Başta uzun gelir ama kalıp hep aynıdır. İstersen PyTorch Lightning ya da fastai gibi katmanlar bu döngüyü senin yerine yazar; Lightning konusunda anlatıyoruz.' },
  { q: 'En sık yapılan hatalar ne?', a: 'Türevleri temizlemeyi unutmak (zero_grad), eğitim ve değerlendirme modlarını karıştırmak (model.eval), tensör şekillerinin uyuşmaması, öğrenme oranını çok büyük seçmek (kayıp nan olur) ve veriyi yanlış normalize etmek. Hile ve Hata konusu bunları tek tek çözüyor.' },
  { q: 'Ön koşul ne?', a: 'Python, biraz NumPy (dizi işlemleri), Yapay Zeka Temelleri\'ndeki sinir ağı, gradyan ve kayıp kavramları, Makine Öğrenmesi\'ndeki değerlendirme ve overfitting mantığı. Matematik olarak "matris çarpımı bir katmandır" fikri yeter.' },
  { q: 'Hugging Face ile ilişkisi ne?', a: 'Hugging Face\'in Transformers kütüphanesi PyTorch üstünde hazır modeller sunar: iki satırda Türkçe BERT ile duygu analizi. Bu bölümde metin ve görüntü konularında kullanacağız; Fine-tuning başlığı tamamen buna ayrılmış.' },
  { q: 'Hangi sırayla ilerlemeli?', a: 'Soldaki sıra: Tensör → Model → Eğitim Döngüsü → Veri → CNN (görüntü) → Transfer Öğrenme → Metin → Ses ve Diğer → Hile ve Hata → Lightning → Kaydetme ve Servis. İlk dört konu temeldir; Transfer Öğrenme en çok işine yarayacak olan.' },
]

